use flux_cli::prelude::*;

#[flux::command]
async fn main(ctx: Ctx) {
  let args = ctx
    .parse::<CliArgs>()
    .await?;

  match args.subcommand {
    Sub::Build(b) => b.run().await,
    Sub::Deploy(d) => d.run().await,
    _ => ctx.help(),
  }
}

const offscreen =
  canvas.transferControlToOffscreen();

const worker = new Worker(
  './render.worker.js'
);

worker.postMessage(
  { type: 'init', canvas: offscreen },
  [offscreen]
);

// delta-encoded ops at 60fps
onOp(op => worker.postMessage({
  type: 'op', ...op
}));
